{
  "implementation": "from collections import defaultdict

def solve(case):
    nodes = case.get('nodes')
    required_symbols = case.get('required_symbols')
    if not nodes or not required_symbols:
        raise ValueError('Missing nodes or required_symbols')

    node_dict = {}
    children = defaultdict(list)
    root_id = None
    for n in nodes:
        nid = n.get('id')
        parent = n.get('parent')
        symbol = n.get('symbol')
        depth = n.get('depth')
        removable = n.get('removable')
        if nid is None or symbol is None or depth is None or removable is None:
            raise ValueError('Node missing required fields')
        node_dict[nid] = n
        if parent is None:
            if root_id is not None:
                raise ValueError('Multiple roots')
            root_id = nid
        else:
            children[parent].append(nid)
    if root_id is None:
        raise ValueError('No root node')

    # Validate all parent references exist
    for n in nodes:
        pid = n.get('parent')
        if pid is not None and pid not in node_dict:
            raise ValueError(f'Parent {pid} not found for node {n["id"]}')

    required_symbols_set = set(required_symbols)
    # Check initial presence of all required symbols
    initial_symbols = {n['symbol'] for n in nodes}
    if not required_symbols_set.issubset(initial_symbols):
        raise ValueError('Required symbols missing from initial tree')

    retained = set(node_dict.keys())
    removed_order = []

    # Sort nodes by depth descending, then id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))

    for node in sorted_nodes:
        nid = node['id']
        if nid not in retained:
            continue
        # Conditions forbidding removal
        if not node['removable']:
            continue
        if node['symbol'] in required_symbols_set:
            continue
        if nid == root_id:
            continue
        # Check if any child is still retained
        child_ids = children.get(nid, [])
        if any(cid in retained for cid in child_ids):
            continue
        # Compute current subtree of retained nodes under this node
        subtree = set()
        stack = [nid]
        while stack:
            cur = stack.pop()
            if cur in retained and cur not in subtree:
                subtree.add(cur)
                stack.extend(children.get(cur, []))
        # Check required symbols after removal
        remaining = retained - subtree
        symbols_remaining = {node_dict[nid2]['symbol'] for nid2 in remaining}
        if required_symbols_set.issubset(symbols_remaining):
            retained = remaining
            removed_order.append(nid)

    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_sorted
    }
